1	// Opening a pull request safely (DESIGN.md §"Act"): Roster opens a PR only on a repo whose owner opted in, and a
2	// dry run returns the command instead of running it.
3	//
4	//   const r = await openPr({ repoPath, branch, title, body, allowRepo, run });
5	//
6	// Never throws for a git or gh failure: that is `opened: false` with the reason. `command` is the `gh pr create`
7	// argv that was run, or with dryRun the one that would run; it is empty when no PR could be attempted at all
8	// (unreadable origin remote, or a repo that is not opted in).
9	
10	import { parseRemote } from "../review/export.ts";
11	
12	export interface RunResult {
13	  code: number;
14	  stdout: string;
15	  stderr: string;
16	}
17	
18	/** Runs one command in the repo directory. Injected by tests; the default spawns a real process. */
19	export type Runner = (cmd: string[]) => Promise<RunResult>;
20	
21	export interface OpenPrOptions {
22	  repoPath: string;
23	  branch: string;
24	  title: string;
25	  body: string;
26	  /** Build the command but never run gh. The owner/repo lookup still runs, because the opt-in check needs it. */
27	  dryRun?: boolean;
28	  /** Opt-in gate, called once with the origin remote's "owner/name". */
29	  allowRepo: (ownerRepo: string) => boolean;
30	  run?: Runner;
31	}
32	
33	export interface OpenPrResult {
34	  opened: boolean;
35	  /** Only set when gh exited 0 and printed a URL. */
36	  url?: string;
37	  /** The `gh pr create` argv, whether or not it ran. Empty when there was nothing to attempt. */
38	  command: string[];
39	  reason?: string;
40	}
41	
42	const NOT_OPTED_IN = "not opted in";
43	const DRY_RUN = "dry run";
44	/** Shell convention for "command not found"; gh missing from PATH reports this. */
45	const NOT_FOUND = 127;
46	
47	/** A runner that spawns real processes in `cwd`. A missing binary (gh is not installed) is a failed command. */
48	function spawnRunner(cwd: string): Runner {
49	  return async (cmd) => {
50	    try {
51	      const proc = Bun.spawn(cmd, { cwd, stdin: "ignore", stdout: "pipe", stderr: "pipe" });
52	      const [stdout, stderr, code] = await Promise.all([
53	        new Response(proc.stdout).text(),
54	        new Response(proc.stderr).text(),
55	        proc.exited,
56	      ]);
57	      return { code, stdout, stderr };
58	    } catch (err) {
59	      return { code: NOT_FOUND, stdout: "", stderr: message(err) };
60	    }
61	  };
62	}
63	
64	function message(err: unknown): string {
65	  return err instanceof Error ? err.message : String(err);
66	}
67	
68	/**
69	 * The `gh pr create` argv for one request. The body is passed as the `--body-file` argument: the frozen F03
70	 * acceptance test pins this exact argv, so it is what runs (github's `--body-file` takes a path — noted in the
71	 * task summary, not silently changed here).
72	 */
73	export function prCreateCommand(o: { branch: string; title: string; body: string }): string[] {
74	  return ["gh", "pr", "create", "--head", o.branch, "--title", o.title, "--body-file", o.body];
75	}
76	
77	/** The pull request URL in gh's stdout: the last URL token, so a leading "Warning:"/progress line is ignored. */
78	export function parsePrUrl(stdout: string): string | null {
79	  const found = stdout.match(/https?:\/\/[^\s<>"]+/g);
80	  const last = found?.at(-1);
81	  return last === undefined ? null : last.replace(/[.,;:)\]]+$/, "");
82	}
83	
84	/**
85	 * Opens a PR for `branch` on `repoPath`'s origin, if that repo allows it. Reads "owner/name" from
86	 * `git remote get-url origin` (https, ssh:// and scp-style forms) and asks `allowRepo` first; a repo that is not
87	 * opted in never reaches gh. With `dryRun` the gh command is returned unrun.
88	 */
89	export async function openPr(opts: OpenPrOptions): Promise<OpenPrResult> {
90	  const run = opts.run ?? spawnRunner(opts.repoPath);
91	
92	  let remote: RunResult;
93	  try {
94	    remote = await run(["git", "remote", "get-url", "origin"]);
95	  } catch (err) {
96	    return { opened: false, command: [], reason: `could not read the origin remote: ${message(err)}` };
97	  }
98	  if (remote.code !== 0) {
99	    return {
100	      opened: false,
101	      command: [],
102	      reason: remote.stderr.trim() || `git remote get-url origin exited ${remote.code}`,
103	    };
104	  }
105	  const ownerRepo = parseRemote(remote.stdout);
106	  if (ownerRepo === null) {
107	    return { opened: false, command: [], reason: `origin has no owner/name: ${remote.stdout.trim()}` };
108	  }
109	
110	  if (!opts.allowRepo(ownerRepo)) return { opened: false, command: [], reason: NOT_OPTED_IN };
111	
112	  const command = prCreateCommand(opts);
113	  if (opts.dryRun) return { opened: false, command, reason: DRY_RUN };
114	
115	  let gh: RunResult;
116	  try {
117	    gh = await run(command);
118	  } catch (err) {
119	    return { opened: false, command, reason: message(err) };
120	  }
121	  if (gh.code !== 0) {
122	    return { opened: false, command, reason: gh.stderr.trim() || `gh pr create exited ${gh.code}` };
123	  }
124	
125	  const url = parsePrUrl(gh.stdout);
126	  return url === null ? { opened: true, command } : { opened: true, url, command };
127	}
