1	// Writes one observational review to reports/<slug>/: review.json (the Review type, validated before
2	// it is written), sessions.json, outcomes.json and review.md. See docs/DESIGN.md §"Data model" and §"Review".
3	import { mkdirSync, writeFileSync } from "node:fs";
4	import { basename, join, resolve } from "node:path";
5	import { inferenceAccuracy, parseTag } from "../identity/index.ts";
6	import { aggregateBySetup, type ScoredOutcome, sessionCostDetail, UNKNOWN_SETUP } from "../score/index.ts";
7	import type { EvidenceLevel, Outcome, Review, ReviewLabel, ReviewTags, Session, SetupRow } from "../types.ts";
8	
9	/** Keys of the Review type in src/types.ts. Kept in step by the `satisfies Review` check in tests. */
10	export const REVIEW_KEYS = [
11	  "id",
12	  "repo",
13	  "created_at",
14	  "generated_at",
15	  "has_entire_data",
16	  "setups",
17	  "label",
18	  "suspect",
19	  "odds_ratio",
20	  "ci95",
21	  "p_value",
22	  "evidence_level",
23	] as const;
24	
25	/** Keys that may be absent: `tags` is written only when sessions carry prompt tags. */
26	export const OPTIONAL_REVIEW_KEYS = ["tags"] as const;
27	
28	export const SETUP_ROW_KEYS = [
29	  "setup_id",
30	  "label",
31	  "harness",
32	  "model",
33	  "rules_hash",
34	  "sessions",
35	  "mature_sessions",
36	  "spend_usd",
37	  "priced_sessions",
38	  "spend_lower_bound",
39	  "unattended",
40	  "survival",
41	  "reverted",
42	  "rework_human",
43	  "surviving_changes",
44	  "cost_per_surviving_change",
45	  "evidence_level",
46	] as const satisfies readonly (keyof SetupRow)[];
47	
48	const LABELS: readonly ReviewLabel[] = ["suspect", "no_suspect", "insufficient_data"];
49	const EVIDENCE: readonly EvidenceLevel[] = ["A", "B", "C"];
50	
51	const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
52	const isFiniteNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
53	
54	/** "owner/name" for a GitHub URL, otherwise the last path segment. */
55	export function repoLabel(repo: string): string {
56	  const trimmed = repo.trim();
57	  const remote = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?\/?$/.exec(trimmed);
58	  if (remote) return `${remote[1]}/${remote[2]}`;
59	  return basename(trimmed.replace(/\/+$/, "").replace(/\.git$/, ""));
60	}
61	
62	const URL_FORM = /^[a-z][a-z0-9+.-]*:\/\/|^[^/@\s]+@[^/:\s]+:/i;
63	
64	/** "owner/name" from an https, ssh:// or scp-style (git@host:owner/name) remote URL; null for anything else. */
65	export function parseRemote(url: string): string | null {
66	  const u = url.trim();
67	  if (!URL_FORM.test(u)) return null;
68	  const m = /[/:]([^/:\s]+)\/([^/\s]+?)(?:\.git)?\/?$/.exec(u);
69	  return m ? `${m[1]}/${m[2]}` : null;
70	}
71	
72	/**
73	 * The review's repo slug "owner/name". A URL is parsed directly. A local path uses its `origin` remote, and with
74	 * no remote (or one that does not parse) falls back to the directory's basename.
75	 */
76	export function repoSlug(repo: string): string {
77	  const direct = parseRemote(repo);
78	  if (direct !== null) return direct;
79	  const dir = resolve(repo);
80	  const p = Bun.spawnSync(["git", "remote", "get-url", "origin"], { cwd: dir, stdout: "pipe", stderr: "pipe" });
81	  const remote = p.exitCode === 0 ? parseRemote(p.stdout.toString()) : null;
82	  return remote ?? basename(dir);
83	}
84	
85	/** Directory name under reports/ for a repo slug: "owner__name", or the bare name. */
86	export function slugDir(slug: string): string {
87	  return slug.replace("/", "__").replace(/[^A-Za-z0-9._-]+/g, "-");
88	}
89	
90	/** Directory name under reports/: "owner__name" for GitHub repos (the web app's lookup form), else the basename. */
91	export function reviewSlug(repo: string): string {
92	  return repoLabel(repo).replace("/", "__").replace(/[^A-Za-z0-9._-]+/g, "-");
93	}
94	
95	/** Mature-session rates: null when mature_sessions is 0. `unattended` is over all sessions with a known prompt count. */
96	const MATURE_RATE_KEYS = ["survival", "reverted", "rework_human"] as const;
97	const RATE_KEYS = ["unattended", ...MATURE_RATE_KEYS] as const;
98	
99	function validateSetupRow(row: unknown, at: string): string[] {
100	  if (!isRecord(row)) return [`${at} must be an object`];
101	  const errs: string[] = [];
102	  for (const k of SETUP_ROW_KEYS) if (!(k in row)) errs.push(`${at} missing ${k}`);
103	  for (const k of Object.keys(row)) if (!(SETUP_ROW_KEYS as readonly string[]).includes(k)) errs.push(`${at} unexpected key ${k}`);
104	  for (const k of ["setup_id", "label", "harness", "model"] as const) {
105	    if (typeof row[k] !== "string" || row[k] === "") errs.push(`${at}.${k} must be a non-empty string`);
106	  }
107	  if (row.rules_hash !== null && typeof row.rules_hash !== "string") errs.push(`${at}.rules_hash must be a string or null`);
108	  for (const k of ["sessions", "mature_sessions"] as const) {
109	    if (!Number.isInteger(row[k]) || (row[k] as number) < 0) errs.push(`${at}.${k} must be a non-negative integer`);
110	  }
111	  if (isFiniteNum(row.sessions) && isFiniteNum(row.mature_sessions) && row.mature_sessions > row.sessions) {
112	    errs.push(`${at}.mature_sessions exceeds sessions`);
113	  }
114	  if (row.spend_usd !== null && !(isFiniteNum(row.spend_usd) && row.spend_usd >= 0)) {
115	    errs.push(`${at}.spend_usd must be null or a number >= 0`);
116	  }
117	  for (const k of ["priced_sessions", "surviving_changes"] as const) {
118	    if (!isFiniteNum(row[k]) || row[k] < 0) errs.push(`${at}.${k} must be a number >= 0`);
119	  }
120	  if (typeof row.spend_lower_bound !== "boolean") errs.push(`${at}.spend_lower_bound must be a boolean`);
121	  if (isFiniteNum(row.priced_sessions) && isFiniteNum(row.sessions) && row.priced_sessions > row.sessions) {
122	    errs.push(`${at}.priced_sessions exceeds sessions`);
123	  }
124	  if (row.cost_per_surviving_change !== null && !(isFiniteNum(row.cost_per_surviving_change) && row.cost_per_surviving_change >= 0)) {
125	    errs.push(`${at}.cost_per_surviving_change must be null or a number >= 0`);
126	  }
127	  for (const k of RATE_KEYS) {
128	    const v = row[k];
129	    if (v !== null && !(isFiniteNum(v) && v >= 0 && v <= 1)) errs.push(`${at}.${k} must be null or a number in [0, 1]`);
130	    if (row.mature_sessions === 0 && v !== null && (MATURE_RATE_KEYS as readonly string[]).includes(k)) {
131	      errs.push(`${at}.${k} must be null when mature_sessions is 0`);
132	    }
133	  }
134	  if (!(EVIDENCE as readonly unknown[]).includes(row.evidence_level)) errs.push(`${at}.evidence_level must be A, B or C`);
135	  return errs;
136	}
137	
138	function validTags(t: unknown): boolean {
139	  if (!isRecord(t) || !isRecord(t.by_tag)) return false;
140	  if (t.tag_accuracy !== null && !(isFiniteNum(t.tag_accuracy) && t.tag_accuracy >= 0 && t.tag_accuracy <= 1)) return false;
141	  return Object.values(t.by_tag).every(
142	    (v) => isRecord(v) && Number.isInteger(v.sessions) && Array.isArray(v.setup_ids) && v.setup_ids.every((x) => typeof x === "string"),
143	  );
144	}
145	
146	/** Lists every way `value` fails the Review type. An empty list means it validates. */
147	export function validateReview(value: unknown): string[] {
148	  if (!isRecord(value)) return ["review must be an object"];
149	  const errs: string[] = [];
150	  for (const k of REVIEW_KEYS) if (!(k in value)) errs.push(`missing ${k}`);
151	  const allowed: readonly string[] = [...REVIEW_KEYS, ...OPTIONAL_REVIEW_KEYS];
152	  for (const k of Object.keys(value)) if (!allowed.includes(k)) errs.push(`unexpected key ${k}`);
153	
154	  for (const k of ["id", "repo", "created_at", "generated_at"] as const) {
155	    if (typeof value[k] !== "string" || value[k] === "") errs.push(`${k} must be a non-empty string`);
156	  }
157	  for (const k of ["created_at", "generated_at"] as const) {
158	    if (typeof value[k] === "string" && Number.isNaN(Date.parse(value[k]))) errs.push(`${k} is not a date`);
159	  }
160	  if (typeof value.has_entire_data !== "boolean") errs.push("has_entire_data must be a boolean");
161	  if (!Array.isArray(value.setups)) errs.push("setups must be an array");
162	  else value.setups.forEach((row, i) => errs.push(...validateSetupRow(row, `setups[${i}]`)));
163	  if ("tags" in value && !validTags(value.tags)) errs.push("tags must be { by_tag, tag_accuracy }");
164	
165	  const label = value.label;
166	  if (!(LABELS as readonly unknown[]).includes(label)) errs.push(`label must be one of ${LABELS.join(", ")}`);
167	  if (label === "suspect") {
168	    if (typeof value.suspect !== "string" || value.suspect === "") errs.push("suspect must name a setup when label is suspect");
169	    if (!isFiniteNum(value.odds_ratio)) errs.push("odds_ratio must be a number when label is suspect");
170	    if (!Array.isArray(value.ci95)) errs.push("ci95 must be set when label is suspect");
171	    if (!isFiniteNum(value.p_value)) errs.push("p_value must be a number when label is suspect");
172	  } else if (value.suspect !== null) {
173	    errs.push("suspect must be null unless label is suspect");
174	  }
175	
176	  if (value.odds_ratio !== null && !(isFiniteNum(value.odds_ratio) && value.odds_ratio >= 0)) {
177	    errs.push("odds_ratio must be null or a number >= 0");
178	  }
179	  const ci = value.ci95;
180	  if (ci !== null) {
181	    const ok = Array.isArray(ci) && ci.length === 2 && ci.every(isFiniteNum) && ci[0]! <= ci[1]!;
182	    if (!ok) errs.push("ci95 must be null or [low, high] with low <= high");
183	  }
184	  if (value.p_value !== null && !(isFiniteNum(value.p_value) && value.p_value >= 0 && value.p_value <= 1)) {
185	    errs.push("p_value must be null or a number in [0, 1]");
186	  }
187	  if (!(EVIDENCE as readonly unknown[]).includes(value.evidence_level)) errs.push("evidence_level must be A, B or C");
188	  return errs;
189	}
190	
191	/** Per-setup numbers for review.md. Rates are null when no mature session supports them. */
192	export interface SetupSummary {
193	  setup_id: string;
194	  label: string;
195	  sessions: number;
196	  mature: number;
197	  spend_usd: number;
198	  unpriced: number;
199	  /** Mean survival over mature sessions. */
200	  survival: number | null;
201	  /** Share of mature sessions that were reverted. */
202	  reverted: number | null;
203	  /** Mean human rework share over mature sessions. */
204	  rework_human: number | null;
205	  /** Share of sessions with a known prompt count that needed exactly one user prompt, mature or not. */
206	  unattended: number | null;
207	}
208	
209	/**
210	 * Display labels per setup_id: "harness · model", plus " (rules a1b2c3)" (first 6 chars of rules_hash) when
211	 * another setup shares the harness and model. Session does not record which rules files were loaded, so the
212	 * hash is the only discriminator available here.
213	 */
214	function setupLabels(sessions: Session[]): Map<string, string> {
215	  const first = new Map<string, Session>();
216	  for (const s of sessions) if (s.setup_id !== null && !first.has(s.setup_id)) first.set(s.setup_id, s);
217	  const plain = (s: Session) => `${s.harness} · ${s.model}`;
218	  const shared = new Map<string, number>();
219	  for (const s of first.values()) shared.set(plain(s), (shared.get(plain(s)) ?? 0) + 1);
220	  return new Map(
221	    [...first].map(([id, s]) => {
222	      const base = plain(s);
223	      if ((shared.get(base) ?? 0) < 2) return [id, base];
224	      return [id, `${base} (rules ${s.rules_hash === null ? "unknown" : s.rules_hash.slice(0, 6)})`];
225	    }),
226	  );
227	}
228	
229	const mean = (xs: number[]): number | null => (xs.length === 0 ? null : xs.reduce((a, b) => a + b, 0) / xs.length);
230	
231	/** Groups sessions by setup_id. Sessions with no setup are left out; the caller counts them. */
232	export function summarizeSetups(sessions: Session[], outcomes: Outcome[]): SetupSummary[] {
233	  const byId = new Map<string, Outcome>(outcomes.map((o) => [o.session_id, o]));
234	  const labels = setupLabels(sessions);
235	  const groups = new Map<string, Session[]>();
236	  for (const s of sessions) {
237	    if (s.setup_id === null) continue;
238	    (groups.get(s.setup_id) ?? groups.set(s.setup_id, []).get(s.setup_id)!).push(s);
239	  }
240	  return [...groups]
241	    .sort(([a], [b]) => a.localeCompare(b))
242	    .map(([setup_id, group]) => {
243	      const outs = group.map((s) => byId.get(s.id)).filter((o): o is Outcome => o?.status === "mature");
244	      const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
245	      const survival = outs.map((o) => o.survival).filter((x): x is number => x !== null);
246	      const reverted = outs.map((o) => o.reverted).filter((x): x is boolean => x !== null);
247	      const human = outs.map((o) => o.rework_human).filter((x): x is number => x !== null);
248	      const unattended = group.map((s) => byId.get(s.id)?.unattended).filter((x): x is boolean => x !== undefined && x !== null);
249	      const priced = group.map((s) => s.cost_usd).filter((x): x is number => x !== null);
250	      const first = group[0]!;
251	      return {
252	        setup_id,
253	        label: labels.get(setup_id)!,
254	        sessions: group.length,
255	        mature: outs.length,
256	        spend_usd: sum(priced),
257	        unpriced: group.length - priced.length,
258	        survival: mean(survival),
259	        reverted: reverted.length === 0 ? null : reverted.filter(Boolean).length / reverted.length,
260	        rework_human: mean(human),
261	        unattended: unattended.length === 0 ? null : unattended.filter(Boolean).length / unattended.length,
262	      };
263	    });
264	}
265	
266	/**
267	 * One row per known setup, built with aggregateBySetup. Sessions with no setup are left out (the review notes
268	 * count them). Rates are fractions of mature sessions; rework_human is the mean over mature sessions that have it.
269	 */
270	export function buildSetupRows(sessions: Session[], outcomes: Outcome[]): SetupRow[] {
271	  const byId = new Map<string, Outcome>(outcomes.map((o) => [o.session_id, o]));
272	  const scored: ScoredOutcome[] = [];
273	  for (const s of sessions) {
274	    const o = byId.get(s.id);
275	    if (!o || s.setup_id === null) continue;
276	    scored.push({
277	      ...o,
278	      setup_id: s.setup_id,
279	      commit_sha: s.commit_sha,
280	      cost_usd: s.cost_usd,
281	      censored: o.status === "mature" ? null : s.commit_sha === null ? "no_commit" : "too_young",
282	    });
283	  }
284	  const first = new Map<string, Session>();
285	  for (const s of sessions) if (s.setup_id !== null && !first.has(s.setup_id)) first.set(s.setup_id, s);
286	
287	  const labels = setupLabels(sessions);
288	
289	  return aggregateBySetup(scored)
290	    .filter((a) => a.setup_id !== UNKNOWN_SETUP)
291	    .map((a) => {
292	      const s = first.get(a.setup_id)!;
293	      const human = scored
294	        .filter((o) => o.setup_id === a.setup_id && o.status === "mature" && o.rework_human !== null)
295	        .map((o) => o.rework_human as number);
296	      const rate = (n: number) => (a.mature === 0 ? null : n / a.mature);
297	      return {
298	        setup_id: a.setup_id,
299	        label: labels.get(a.setup_id)!,
300	        harness: s.harness,
301	        model: s.model,
302	        rules_hash: s.rules_hash,
303	        sessions: a.sessions,
304	        mature_sessions: a.mature,
305	        spend_usd: a.cost_usd,
306	        priced_sessions: a.priced_sessions,
307	        spend_lower_bound: sessions.some(
308	          (x) => x.setup_id === a.setup_id && x.cost_usd !== null && sessionCostDetail({ ...x, cost_usd: null }).lower_bound,
309	        ),
310	        unattended: a.unattended_known === 0 ? null : a.unattended / a.unattended_known,
311	        survival: a.survival_mean,
312	        reverted: rate(a.reverted),
313	        rework_human: mean(human),
314	        surviving_changes: a.survival_sum,
315	        cost_per_surviving_change: a.cost_per_surviving_change,
316	        evidence_level: "A",
317	      };
318	    });
319	}
320	
321	/** The `tags` block, or undefined when no session's first prompt carries a `[roster setup=…]` tag. */
322	export function buildTags(sessions: Session[]): ReviewTags | undefined {
323	  const tagged = sessions.map((s) => ({ setupId: s.setup_id, tag: parseTag(s.first_prompt) }));
324	  if (tagged.every((t) => t.tag === null)) return undefined;
325	  const ids = new Map<string, { sessions: number; ids: Set<string> }>();
326	  for (const { setupId, tag } of tagged) {
327	    if (tag === null) continue;
