// F40: the opt-in registry (docs/DESIGN.md §"Act"). Roster never acts on another team's repo unless that team
// opted in, and then only in the ways it allowed. `loadOptIns` reads the registry; `isAllowed` asks it about one
// action. Both fail closed — a malformed entry is dropped, an unknown repo is denied for every action.
//
//   const optIns = loadOptIns(JSON.parse(await Bun.file(path).text()));
//   const allowRepo = (ownerRepo: string) => isAllowed(optIns, ownerRepo, "open-pr");

/** One team's opt-in. `replyUrl` is present only when the entry carried an https URL. */
export interface OptIn {
  repo: string;
  public: boolean;
  prAllowed: boolean;
  replyUrl?: string;
}

/** The two things Roster might do on someone else's repo. */
export type OptInAction = "review-public" | "open-pr";

/** Matches the `isRecord` helper in review/export.ts: an object that is not null and not an array. */
const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** The string itself when `value` parses as an https URL, otherwise undefined. */
function httpsUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  try {
    return new URL(trimmed).protocol === "https:" ? trimmed : undefined;
  } catch {
    return undefined;
  }
}

/**
 * The usable opt-ins in `json`, in input order. `json` is already-parsed JSON (the registry is usually an array
 * of entries); anything that is not an array yields no opt-ins. An entry is dropped unless it is an object with a
 * non-empty string `repo` and boolean `public` and `prAllowed`, so a typo can never widen what Roster may do.
 * `replyUrl` survives only as a well-formed https URL; other values leave the key off entirely.
 */
export function loadOptIns(json: unknown): OptIn[] {
  if (!Array.isArray(json)) return [];
  const optIns: OptIn[] = [];
  for (const entry of json) {
    if (!isRecord(entry)) continue;
    const { repo, public: isPublic, prAllowed } = entry;
    if (typeof repo !== "string" || repo.trim() === "") continue;
    if (typeof isPublic !== "boolean" || typeof prAllowed !== "boolean") continue;
    const replyUrl = httpsUrl(entry.replyUrl);
    const optIn: OptIn = { repo: repo.trim(), public: isPublic, prAllowed };
    if (replyUrl !== undefined) optIn.replyUrl = replyUrl;
    optIns.push(optIn);
  }
  return optIns;
}

/**
 * Whether `repo` ("owner/name", compared case-insensitively) may have `action` done to it. Lookup is exact, not a
 * prefix: "Some/Repo2" is not "Some/Repo". An unknown repo, and an entry that only allows the other action, are
 * both false. When a repo appears more than once the first entry wins, so the registry stays the single word on
 * what is allowed.
 */
export function isAllowed(optIns: readonly OptIn[], repo: string, action: OptInAction): boolean {
  const wanted = repo.trim().toLowerCase();
  const optIn = optIns.find((o) => o.repo.toLowerCase() === wanted);
  if (optIn === undefined) return false;
  switch (action) {
    case "review-public":
      return optIn.public;
    case "open-pr":
      return optIn.prAllowed;
    default:
      return false;
  }
}

