  test("a non-array or unparsed registry yields no opt-ins", () => {
    expect(loadOptIns(null)).toEqual([]);
    expect(loadOptIns(undefined)).toEqual([]);
    expect(loadOptIns({ optIns: [GOOD] })).toEqual([]);
    expect(loadOptIns('{"repo":"Some/Repo"}')).toEqual([]);
  });

  test("trims surrounding whitespace from repo", () => {
    const [parsed] = loadOptIns([{ repo: "  Some/Repo  ", public: true, prAllowed: true }]);

    expect(parsed!.repo).toBe("Some/Repo");
  });

  test("drops unknown keys rather than carrying them through", () => {
    const [parsed] = loadOptIns([{ ...GOOD, note: "hello", Public: true }]);

    expect(parsed).toEqual({ repo: "Some/Repo", public: true, prAllowed: true });
  });

  test("keeps replyUrl only when it is an https URL", () => {
    const kept = loadOptIns([
      { repo: "A/B", public: true, prAllowed: true, replyUrl: "https://example.com/hook" },
      { repo: "C/D", public: true, prAllowed: true, replyUrl: "  https://example.com/hook?x=1  " },
    ]);
    expect(kept[0]!.replyUrl).toBe("https://example.com/hook");
    expect(kept[1]!.replyUrl).toBe("https://example.com/hook?x=1");

    const dropped = loadOptIns([
      { repo: "E/F", public: true, prAllowed: true, replyUrl: "http://example.com/hook" },
      { repo: "G/H", public: true, prAllowed: true, replyUrl: "ftp://example.com/hook" },
      { repo: "I/J", public: true, prAllowed: true, replyUrl: "example.com/hook" },
      { repo: "K/L", public: true, prAllowed: true, replyUrl: "https://" },
      { repo: "M/N", public: true, prAllowed: true, replyUrl: 42 },
      { repo: "O/P", public: true, prAllowed: true, replyUrl: null },
    ]);
    for (const entry of dropped) {
      expect(entry.replyUrl).toBeUndefined();
      // The entry itself survives; only the unusable URL is gone.
      expect(entry.public).toBe(true);
    }
  });
});

describe("isAllowed", () => {
  const optIns = loadOptIns([
    { repo: "Some/Repo", public: true, prAllowed: true },
    { repo: "PublicOnly/Repo", public: true, prAllowed: false },
    { repo: "PrOnly/Repo", public: false, prAllowed: true },
    { repo: "Neither/Repo", public: false, prAllowed: false },
  ]);

  test("denies an unknown repo for every action", () => {
    expect(isAllowed(optIns, "Unknown/Repo", "review-public")).toBe(false);
    expect(isAllowed(optIns, "Unknown/Repo", "open-pr")).toBe(false);
    // Exact match on owner/repo, not a prefix.
    expect(isAllowed(optIns, "Some/Repo2", "review-public")).toBe(false);
    expect(isAllowed(optIns, "Some", "review-public")).toBe(false);
    expect(isAllowed(optIns, "Repo", "open-pr")).toBe(false);
  });

  test("denies everything against an empty registry", () => {
    expect(isAllowed([], "Some/Repo", "review-public")).toBe(false);
    expect(isAllowed([], "Some/Repo", "open-pr")).toBe(false);
  });

  test("compares repo names case-insensitively", () => {
    expect(isAllowed(optIns, "some/repo", "review-public")).toBe(true);
    expect(isAllowed(optIns, "SOME/REPO", "open-pr")).toBe(true);
    expect(isAllowed(optIns, "sOmE/rEpO", "open-pr")).toBe(true);
    expect(isAllowed(optIns, "  Some/Repo  ", "review-public")).toBe(true);
  });

  test("review-public needs public true, whatever prAllowed says", () => {
    expect(isAllowed(optIns, "Some/Repo", "review-public")).toBe(true);
    expect(isAllowed(optIns, "PublicOnly/Repo", "review-public")).toBe(true);
    expect(isAllowed(optIns, "PrOnly/Repo", "review-public")).toBe(false);
    expect(isAllowed(optIns, "Neither/Repo", "review-public")).toBe(false);
  });

  test("open-pr needs prAllowed true, whatever public says", () => {
    expect(isAllowed(optIns, "Some/Repo", "open-pr")).toBe(true);
    expect(isAllowed(optIns, "PrOnly/Repo", "open-pr")).toBe(true);
    expect(isAllowed(optIns, "PublicOnly/Repo", "open-pr")).toBe(false);
    expect(isAllowed(optIns, "Neither/Repo", "open-pr")).toBe(false);
  });

  test("an action outside the two defined ones is denied", () => {
    expect(isAllowed(optIns, "Some/Repo", "merge" as OptInAction)).toBe(false);
  });

  test("the first entry for a duplicated repo wins", () => {
    const duplicated = loadOptIns([
      { repo: "Dup/Repo", public: false, prAllowed: false },
      { repo: "dup/repo", public: true, prAllowed: true },
    ]);

    expect(isAllowed(duplicated, "Dup/Repo", "review-public")).toBe(false);
    expect(isAllowed(duplicated, "Dup/Repo", "open-pr")).toBe(false);
  });
});
